// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FeeSetting) predicate.FeeSetting {
	return predicate.FeeSetting(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FeeSetting) predicate.FeeSetting {
	return predicate.FeeSetting(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FeeSetting) predicate.FeeSetting {
	return predicate.FeeSetting(sql.NotPredicates(p))
}
